import {MODES,dateKey,shiftDate,weekStart,seed,leaves,descendants,moveNode,deleteNode,setting,applyPending,plan,toggleLog,ancestry,stats,validate} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{const raw=localStorage.getItem('jiku-v1');state=raw?validate(JSON.parse(raw)):seed()}catch{state=seed();setTimeout(()=>toast('保存データを読み込めません。設定からバックアップを確認してください。'),300)}
let view='home',today=dateKey(),selected=today,month=today.slice(0,7),focus=null,zoom=1,pan={x:0,y:0};
function save(){try{localStorage.setItem('jiku-v1',JSON.stringify(state))}catch{toast('保存できませんでした。設定からバックアップを保存してください。')}}
applyPending(state,today);save();
const icon=(name)=>({home:'⌂',tree:'♧',calendar:'▦',stats:'◴',settings:'⚙'}[name]);
const names={home:'ホーム',tree:'自分の木',calendar:'カレンダー',stats:'統計'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){const d=$('#dialog');d.innerHTML=html;d.showModal();d.querySelector('[autofocus]')?.focus()}
function close(){$('#dialog').close()}
function heading(k,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function render(){const latest=dateKey();if(today!==latest){today=latest;selected=today;applyPending(state,today);save()}$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home">jiku<span>●</span></a><p class="brand-note">自分の軸を、日々の行動へ。</p><nav>${Object.entries(names).map(([k,v])=>`<button class="nav ${view===k?'active':''}" data-view="${k}"><span>${icon(k)}</span>${v}${view===k?'<i></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="little-tree">♧</div><p>小さな一歩が、<br>あなたの木を育てる。</p><button class="settings" data-do="settings">⚙ <span>設定・バックアップ</span></button><small>MADE FOR YOUR OWN PACE</small></div></aside><main><header class="topbar"><span>MY PERSONAL GARDEN</span><div><span class="local-indicator">● このブラウザに保存</span><button class="avatar" data-do="settings" aria-label="設定">J</button></div></header><div class="content">${({home:home,tree:treePage,calendar:calendarPage,stats:statsPage}[view])()}</div><footer>根を張って、少しずつ。 <span>jiku</span></footer></main>`;bindTree()}
function modeCards(key){const current=state.records[key]?.mode;return `<div class="mode-grid">${Object.entries(MODES).filter(([k])=>k!=='none').map(([k,m])=>`<button class="mode-card ${current===k?'selected':''} ${k}" data-mode="${k}" data-date="${key}"><span class="mode-icon">${m.icon}</span><span><strong>${m.label}</strong><small>${m.description}</small></span><span class="radio">${current===k?'✓':''}</span></button>`).join('')}</div>`}
function home(){const mode=state.records[today]?.mode,actions=mode?plan(state,mode):[],logs=state.logs[today]||{},ws=weekStart(today),summary=stats(state,ws,today);return `${heading('TODAY, AT YOUR OWN PACE','今日も、自分のペースで。','大きな目標も、今日の小さな一歩から。',`<div class="date-badge"><strong>${Number(today.slice(5,7))}<span> / </span>${Number(today.slice(8))}</strong><small>${new Intl.DateTimeFormat('ja-JP',{weekday:'long',timeZone:'Asia/Tokyo'}).format(new Date())}</small></div>`)}<section class="mode-section"><div class="section-title"><h2>今日は、どんな一日にする？</h2><span>いつでも変更できます</span></div>${modeCards(today)}<button class="text-button quiet" data-mode="none" data-date="${today}">今日は取り組めなかった日として記録 ${mode==='none'?'✓':''}</button></section><div class="home-grid"><section class="card action-panel"><div class="section-title"><div><div class="eyebrow">SMALL STEPS</div><h2>今日の行動</h2></div><span class="pill">${Object.keys(logs).length} 個の実行記録</span></div>${mode?`<p class="muted">${MODES[mode].label}の、あなたのためのプラン。</p>`:'<p class="muted">上から今日のモードを選んで、はじめましょう。</p>'}<div class="actions">${actions.map(n=>actionRow(n,today)).join('')||`<div class="empty"><span>${mode==='rest'?'☾':'♧'}</span><h3>${mode==='rest'?'ゆっくり、根を休めよう。':mode?'小さな一歩を、木に追加しよう。':'今日に合ったペースを。'}</h3><p>${mode==='rest'?'休息も、大切なあなたの時間です。':'「自分の木」で目標と行動を育てられます。'}</p></div>`}</div>${Object.entries(logs).filter(([id])=>!actions.some(n=>n.id===id)).map(([id,l])=>`<div class="past-log">✓ ${esc(l.name)} <small>今日の実行記録</small></div>`).join('')}<button class="text-button" data-view="tree">木から行動を見直す <span>↗</span></button></section><section class="card garden-card"><div class="section-title"><div><div class="eyebrow">YOUR ROOTS, YOUR WAY</div><h2>あなたの木</h2></div><button class="round-button" data-view="tree" aria-label="自分の木を開く">↗</button></div><div class="mini-tree">${drawTree(true)}</div><div class="garden-caption"><span>${leaves(state).length} 枚の葉っぱ</span><span>ひとつの想いから、広がる未来。</span></div></section></div><div class="bottom-grid"><section class="card week-card"><div><div class="eyebrow">THIS WEEK</div><h2>今週の足あと</h2><p class="muted">${summary.days}日を記録。どんな日も、あなたの一日。</p></div><div class="week-dots">${Array.from({length:7},(_,i)=>{const k=shiftDate(ws,i);return `<button class="week-day" data-day="${k}" ${k>today?'disabled':''}><span>${['月','火','水','木','金','土','日'][i]}</span><i style="background:${MODES[state.records[k]?.mode]?.color||'#efeee9'}">${k===today?'·':''}</i></button>`}).join('')}</div></section><button class="review-teaser" data-do="review"><div><span class="eyebrow">A MOMENT TO REFLECT</span><h2>今週の自分と、話そう。</h2><p>振り返りから、来週の小さな一歩を。</p></div><span class="review-arrow">↗</span></button></div>`}
function actionRow(n,key){const a=setting(state,n.id),done=!!state.logs[key]?.[n.id];return `<div class="action-row ${done?'done':''}"><button class="check ${done?'checked':''}" data-check="${esc(n.id)}" data-date="${key}" aria-label="${esc(n.name)}の実行記録" aria-pressed="${done}">${done?'✓':''}</button><div class="action-copy"><strong>${esc(n.name)}</strong><small>${esc(ancestry(state,n.id).slice(1,-1).join(' / ')||'自分の木')}</small></div><span class="priority p${a.priority}">${['高','中','低'][a.priority]}</span><button class="edit-action" data-edit="${esc(n.id)}" aria-label="${esc(n.name)}を編集">⋯</button></div>`}
function drawTree(mini=false){const root=state.nodes.find(n=>n.id===(mini?null:focus))||state.nodes.find(n=>n.parentId===null),nodes=[],edges=[];let slot=0;function layout(n,depth){const children=state.nodes.filter(x=>x.parentId===n.id),p={...n,depth};nodes.push(p);if(children.length){const cs=children.map(c=>layout(c,depth+1));p.x=cs.reduce((s,c)=>s+c.x,0)/cs.length;cs.forEach(c=>edges.push([p,c]))}else{p.x=slot++*170}return p}layout(root,0);const maxDepth=Math.max(...nodes.map(n=>n.depth),1),width=Math.max(760,slot*170+100),height=Math.max(480,maxDepth*125+190),maxX=Math.max(...nodes.map(n=>n.x),1);nodes.forEach(n=>{n.x=60+(width-120)*(n.x/maxX);n.y=height-90-n.depth*125});const byId=new Map(nodes.map(n=>[n.id,n]));return `<svg class="tree-svg ${mini?'mini':''}" viewBox="0 0 ${width} ${height}" role="img" aria-label="目標と行動を表す自分の木"><defs><linearGradient id="wood${mini?'m':''}" x2="0" y2="1"><stop stop-color="#658c62"/><stop offset="1" stop-color="#89704e"/></linearGradient></defs><g class="tree-transform" transform="${mini?'':`translate(${pan.x} ${pan.y}) scale(${zoom})`}"><ellipse cx="${byId.get(root.id).x}" cy="${height-34}" rx="108" ry="12" fill="#d7debf" opacity=".5"/><path d="M ${byId.get(root.id).x-38} ${height-30} Q ${byId.get(root.id).x} ${height-70} ${byId.get(root.id).x+38} ${height-30}" fill="none" stroke="#a69572" stroke-width="5"/>${edges.map(([a,b])=>`<path d="M ${a.x} ${a.y} C ${a.x} ${b.y+55},${b.x} ${a.y-45},${b.x} ${b.y}" fill="none" stroke="url(#wood${mini?'m':''})" stroke-width="${Math.max(3,16-a.depth*3)}" stroke-linecap="round"/>`).join('')}${nodes.map(n=>{const leaf=!state.nodes.some(x=>x.parentId===n.id),recorded=Object.values(state.logs).some(v=>v[n.id]);return `<g class="tree-node ${leaf?'leaf':'branch'}" ${mini?'':`data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.name)}"`} transform="translate(${n.x},${n.y})"><title>${esc(n.name)}</title>${leaf?`<path d="M 0 3 C -63 15,-70 -55,-8 -45 C 34 -56,60 -6,0 3" fill="${recorded?'#4d8158':'#89a777'}"/><path d="M -27 -27 L 17 -6" stroke="#d5e2bf" stroke-width="1.5"/>`:`<circle r="${n.parentId?9:13}" fill="#7d8b61" stroke="#fafbf4" stroke-width="4"/>`}<rect x="-77" y="${leaf?12:18}" width="154" height="28" rx="14" fill="#fffef9" opacity=".95"/><text text-anchor="middle" y="${leaf?31:37}" fill="#435a43" font-size="12">${esc(n.name.length>13?n.name.slice(0,12)+'…':n.name)}</text></g>`}).join('')}</g></svg>`}
function treePage(){return `${heading('A LIFE ROOTED IN YOU','自分の木','叶えたい未来を、今日できることへ。',`<button class="primary" data-edit="new">＋ 目標・行動を追加</button>`)}<section class="card tree-card"><div class="tree-toolbar"><span><i class="green-dot"></i> ${state.nodes.length} の目標 · ${leaves(state).length} の行動</span><div><button data-do="zoom-out" aria-label="縮小">−</button><span>${Math.round(zoom*100)}%</span><button data-do="zoom-in" aria-label="拡大">＋</button><button data-do="reset-tree">全体表示</button></div></div><div class="tree-canvas">${drawTree()}</div><div class="tree-help"><span>タップして編集 · ノードを重ねて親を変更 · 背景をドラッグして移動</span><span>枝の太さは重要度を表しません</span></div></section><section class="card tree-list"><div class="section-title"><h2>葉っぱの行動設定</h2><span>モードに合わせて、無理なく。</span></div>${leaves(state).map(n=>`<button class="leaf-list-row" data-edit="${esc(n.id)}"><span class="leaf-bullet">♧</span><div><strong>${esc(n.name)}</strong><small>${esc(ancestry(state,n.id).slice(1,-1).join(' / '))}</small></div><div class="leaf-modes">${setting(state,n.id).modes.map(m=>`<span>${MODES[m].icon}</span>`).join('')}</div><span class="pill">${{active:'有効',paused:'一時停止',completed:'完了'}[setting(state,n.id).status]}</span><span>↗</span></button>`).join('')}</section>`}
function calendarPage(){const [y,m]=month.split('-').map(Number),first=`${month}-01`,offset=(new Date(first+'T12:00:00+09:00').getUTCDay()+6)%7,num=new Date(Date.UTC(y,m,0)).getUTCDate();return `${heading('EVERY DAY HAS ITS OWN COLOR','日々の足あと','がんばった日も、休んだ日も。すべてが、あなたの記録。')}<div class="calendar-layout"><section class="card calendar-card"><div class="month-heading"><h2>${y}<small>年</small> ${m}<small>月</small></h2><div><button class="round-button" data-month="-1" aria-label="前の月">←</button><button class="text-button" data-do="today">今月</button><button class="round-button" data-month="1" aria-label="次の月">→</button></div></div><div class="calendar-grid">${['月','火','水','木','金','土','日'].map(d=>`<span class="day-label">${d}</span>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:num},(_,i)=>{const k=`${month}-${String(i+1).padStart(2,'0')}`,mode=state.records[k]?.mode;return `<button class="day-cell ${selected===k?'selected':''} ${k===today?'today':''}" data-select-date="${k}" ${k>today?'disabled':''}><span>${i+1}</span><i style="background:${MODES[mode]?.color||'#eeede6'}">${mode?MODES[mode].icon:''}</i>${state.logs[k]&&Object.keys(state.logs[k]).length?'<b class="log-dot"></b>':''}</button>`}).join('')}</div><div class="legend">${Object.values(MODES).map(m=>`<span><i style="background:${m.color}"></i>${m.label}</span>`).join('')}<span><i style="background:#eeede6"></i>未記録</span></div></section><section class="card day-detail"><div class="eyebrow">YOUR DAILY NOTE</div><h2>${Number(selected.slice(5,7))}月${Number(selected.slice(8))}日</h2><p class="muted">過去の記録も、ここから変更できます。</p><div class="day-modes">${Object.entries(MODES).map(([k,m])=>`<button class="${state.records[selected]?.mode===k?'chosen':''}" data-mode="${k}" data-date="${selected}"><span style="color:${m.color}">${m.icon}</span>${m.label}<i>${state.records[selected]?.mode===k?'✓':''}</i></button>`).join('')}</div><button class="text-button quiet" data-do="clear-record">未記録に戻す</button><hr><h3>取り組んだ行動</h3>${Object.values(state.logs[selected]||{}).map(l=>`<p class="history-log">✓ ${esc(l.name)}</p>`).join('')||'<p class="muted">実行記録はありません。<br>記録がない行動は、実績不明として扱います。</p>'}</section></div>`}
function statsPage(){const start=shiftDate(today,-29),s=stats(state,start,today),ws=weekStart(today),counts=s.counts,byName={};s.logs.forEach(l=>byName[l.name]=(byName[l.name]||0)+1);return `${heading('LOOK BACK, GROW FORWARD','積み重ねを、見つめる。','数字は評価ではなく、自分を知るためのヒント。',`<span class="range-badge">過去30日間 · ${start.slice(5).replace('-','/')} – ${today.slice(5).replace('-','/')}</span>`)}<div class="stat-grid">${[['記録した日',s.days,'日','30日間の足あと'],['実行を記録した行動',s.logs.length,'回','あなたが残した、小さな一歩'],['休む日',counts.rest,'日','自分を大切にする時間']].map(([l,n,u,d])=>`<section class="card stat-card"><p>${l}</p><strong>${n}<small>${u}</small></strong><span>${d}</span></section>`).join('')}</div><div class="stats-layout"><section class="card"><div class="eyebrow">YOUR RHYTHM</div><h2>日々のモードの割合</h2><p class="muted">どのペースにも、意味がある。</p><div class="distribution">${s.days?Object.entries(counts).map(([k,c])=>`<div style="width:${c/s.days*100}%;background:${MODES[k].color}" title="${MODES[k].label}: ${c}日"></div>`).join(''):'<div style="width:100%;background:#eeede6"></div>'}</div>${Object.entries(counts).map(([k,c])=>`<div class="distribution-row"><i style="background:${MODES[k].color}"></i><span>${MODES[k].label}</span><strong>${c}<small>日</small></strong><em>${s.days?Math.round(c/s.days*100):0}%</em></div>`).join('')}<p class="footnote">未記録 ${30-s.days} 日は割合に含めていません。</p></section><section class="card"><div class="eyebrow">LEAVES YOU NURTURED</div><h2>行動の積み重ね</h2><p class="muted">チェックを残した行動だけを集計しています。</p>${Object.entries(byName).sort((a,b)=>b[1]-a[1]).map(([n,c])=>`<div class="activity-stat"><div><span>${esc(n)}</span><strong>${c} 回</strong></div><div class="activity-track"><i style="width:${c/Math.max(...Object.values(byName))*100}%"></i></div></div>`).join('')||'<div class="empty"><span>♧</span><p>最初の一歩を記録すると、<br>ここに積み重ねが見えてきます。</p></div>'}<p class="footnote">行動回数は、能力や成果そのものを表しません。</p></section></div><section class="review-teaser wide" data-do="review" tabindex="0" role="button"><div><span class="eyebrow">WEEKLY REFLECTION</span><h2>今週を振り返り、来週を整える。</h2><p>${ws.replaceAll('-','/')} からの一週間。無理のないペースを探しましょう。</p></div><button class="primary" data-do="review">週次レビューを開く ↗</button></section>`}
function editor(id){const isNew=id==='new',n=isNew?{name:'',parentId:focus||state.nodes.find(n=>!n.parentId).id}:state.nodes.find(n=>n.id===id),a=isNew?{priority:1,type:'continuous',status:'active',modes:['full']}:setting(state,id),isRoot=!isNew&&!n.parentId,blocked=isNew?new Set():descendants(state,id),isLeaf=isNew||leaves(state).some(n=>n.id===id);modal(`<form id="node-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">GROW YOUR OWN WAY</div><h2>${isNew?'新しい目標・行動':isRoot?'あなたの根っこ':'目標・行動を編集'}</h2></div><button type="button" data-do="close" class="round-button" aria-label="閉じる">×</button></div><label>名前<input autofocus required maxlength="80" name="name" value="${esc(n.name)}" placeholder="例：自分のアプリをつくる"></label>${!isRoot?`<label>つながる親目標<select name="parent">${state.nodes.filter(p=>!blocked.has(p.id)).map(p=>`<option value="${esc(p.id)}" ${p.id===n.parentId?'selected':''}>${esc(ancestry(state,p.id).join(' / '))}</option>`).join('')}</select></label>`:''}${isLeaf?`<div class="form-divider">葉っぱの行動設定</div><div class="form-columns"><label>種類<select name="type"><option value="continuous" ${a.type==='continuous'?'selected':''}>継続型</option><option value="once" ${a.type==='once'?'selected':''}>完了型</option></select></label><label>優先順位<select name="priority">${['高','中','低'].map((p,i)=>`<option value="${i}" ${i===a.priority?'selected':''}>${p}</option>`).join('')}</select></label></div><label>状態<select name="status">${Object.entries({active:'有効',paused:'一時停止',completed:'完了'}).map(([v,t])=>`<option value="${v}" ${v===a.status?'selected':''}>${t}</option>`).join('')}</select></label><fieldset><legend>実行するモード</legend>${['full','busy','rest'].map(m=>`<label class="checkbox-label"><input type="checkbox" name="modes" value="${m}" ${a.modes.includes(m)?'checked':''}>${MODES[m].icon} ${MODES[m].label}</label>`).join('')}</fieldset><p class="footnote">完了型は実行チェックで完了になります。再開は状態を有効に戻してください。</p>`:'<p class="muted">子目標があるため枝として表示されます。末端の目標が葉っぱになります。</p>'}<div class="dialog-actions">${!isNew&&!isRoot?`<button type="button" class="danger text-button" data-delete="${esc(id)}">削除</button><button type="button" class="text-button" data-focus="${esc(id)}">この枝を見る</button>`:''}<button class="primary" type="submit">${isNew?'追加する':'変更を保存'}</button></div></form>`)}
function review(){const ws=weekStart(today),end=shiftDate(ws,6),s=stats(state,ws,end),r=state.reviews[ws]||{},effective=shiftDate(ws,7);modal(`<form id="review-form"><div class="dialog-title"><div><div class="eyebrow">WEEKLY REFLECTION</div><h2>今週の自分と、話そう。</h2></div><button type="button" data-do="close" class="round-button" aria-label="閉じる">×</button></div><p class="muted">${ws.replaceAll('-','/')} — ${end.replaceAll('-','/')}</p><div class="review-summary">${Object.entries(s.counts).map(([k,c])=>`<div><span style="color:${MODES[k].color}">${MODES[k].icon}</span><strong>${c}日</strong><small>${MODES[k].label}</small></div>`).join('')}</div><h3>今週、取り組んだ葉っぱ</h3><p class="muted">${s.logs.length} 回の実行記録</p>${Object.entries(s.logs.reduce((o,l)=>(o[l.name]=(o[l.name]||0)+1,o),{})).map(([n,c])=>`<p class="review-log">♧ ${esc(n)} <b>${c}回</b></p>`).join('')}<label>無理があったこと・気づいたこと<textarea name="note" rows="3" placeholder="今週の自分に、どんな言葉をかけたい？">${esc(r.note||'')}</textarea></label><label>来週、大切にしたいこと<textarea name="next" rows="2" placeholder="小さく、具体的な一歩を書いてみよう。">${esc(r.next||'')}</textarea></label><h3>来週の行動プラン</h3><p class="footnote">${effective.replaceAll('-','/')}（月）から反映。過去の記録はそのまま残ります。</p>${leaves(state).map(n=>{const a=state.pending.find(p=>p.id===n.id&&p.effective===effective)?.setting||setting(state,n.id);return `<fieldset class="review-setting" data-review-node="${esc(n.id)}"><legend>${esc(n.name)}</legend><select aria-label="${esc(n.name)}の来週の優先順位" data-review-priority>${['高','中','低'].map((p,i)=>`<option value="${i}" ${a.priority===i?'selected':''}>優先順位：${p}</option>`).join('')}</select><div>${['full','busy','rest'].map(m=>`<label class="checkbox-label"><input type="checkbox" value="${m}" ${a.modes.includes(m)?'checked':''}>${MODES[m].label}</label>`).join('')}</div></fieldset>`}).join('')}<div class="dialog-actions"><button class="primary">レビューを保存</button></div></form>`)}
function settings(){modal(`<div class="dialog-title"><div><div class="eyebrow">YOUR OWN GARDEN</div><h2>設定・バックアップ</h2></div><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><p>データはこの端末・ブラウザ内に保存されます。端末間での同期はありません。ブラウザのデータを消す前にバックアップしてください。</p><div class="settings-actions"><button class="primary" data-do="export">↓ バックアップを書き出す</button><label class="import-button">↑ バックアップを読み込む<input type="file" id="import" accept="application/json,.json"></label></div><p class="footnote">読み込み時は現在のデータを置き換えます。先に現在のバックアップを保存することをおすすめします。日付は日本時間、週の始まりは月曜日です。</p><hr><p class="muted">jiku v1.0 · 自分の軸を、日々の行動へ。</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-do],[data-view],[data-day],[data-focus]');if(!b)return;const d=b.dataset;if(d.view){view=d.view;location.hash=view;render();window.scrollTo(0,0)}if(d.mode){state.records[d.date]={mode:d.mode};save();render();toast('一日のモードを記録しました')}if(d.check){const n=state.nodes.find(n=>n.id===d.check);if(n){toggleLog(state,d.date,n);save();render()}}if(d.edit)editor(d.edit);if(d.selectDate){selected=d.selectDate;render()}if(d.day){selected=d.day;month=selected.slice(0,7);view='calendar';render()}if(d.month){const [y,m]=month.split('-').map(Number),v=new Date(Date.UTC(y,m-1+Number(d.month),1));month=`${v.getUTCFullYear()}-${String(v.getUTCMonth()+1).padStart(2,'0')}`;render()}if(d.focus){focus=d.focus;zoom=1;pan={x:0,y:0};close();render()}if(d.delete){const id=d.delete,n=state.nodes.find(n=>n.id===id),count=descendants(state,id).size;modal(`<h2>「${esc(n.name)}」を削除しますか？</h2><p>子孫を含め ${count} 個の目標を削除します。過去の実行記録は残ります。</p><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button class="primary danger-bg" data-confirm-delete="${esc(id)}">削除する</button></div>`)}if(d.confirmDelete){deleteNode(state,d.confirmDelete);focus=null;save();close();render();toast('目標を削除しました')}if(d.do)({close,settings,review,'zoom-in':()=>{zoom=Math.min(2.5,zoom+.2);render()},'zoom-out':()=>{zoom=Math.max(.4,zoom-.2);render()},'reset-tree':()=>{focus=null;zoom=1;pan={x:0,y:0};render()},today:()=>{month=today.slice(0,7);selected=today;render()},'clear-record':()=>{delete state.records[selected];save();render();toast('モードを未記録に戻しました')},export:()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`jiku-backup-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}[d.do])?.()});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='node-form'){const f=new FormData(e.target),id=e.target.dataset.id,newId=id==='new'?crypto.randomUUID():id,name=f.get('name').trim();if(!name){toast('名前を入力してください');return}try{if(id==='new')state.nodes.push({id:newId,parentId:f.get('parent'),name});else{const n=state.nodes.find(n=>n.id===id);if(n.parentId)moveNode(state,id,f.get('parent'));n.name=name}if(f.has('type'))state.settings[newId]={type:f.get('type'),priority:Number(f.get('priority')),status:f.get('status'),modes:f.getAll('modes')};save();close();render();toast('木を更新しました')}catch(err){toast(err.message)}}if(e.target.id==='review-form'){const ws=weekStart(today),effective=shiftDate(ws,7),f=new FormData(e.target);state.reviews[ws]={note:f.get('note'),next:f.get('next'),savedAt:new Date().toISOString()};e.target.querySelectorAll('[data-review-node]').forEach(el=>{const id=el.dataset.reviewNode;state.pending=state.pending.filter(p=>!(p.id===id&&p.effective===effective));state.pending.push({id,effective,setting:{...setting(state,id),priority:Number(el.querySelector('select').value),modes:[...el.querySelectorAll('input:checked')].map(i=>i.value)}})});save();close();render();toast('レビューを保存しました。行動設定は来週から反映します。')}});
document.addEventListener('change',async e=>{if(e.target.id==='import'&&e.target.files[0]){try{const f=e.target.files[0];if(f.size>10*1024*1024)throw Error('10MB以下のバックアップを選んでください');const next=validate(JSON.parse(await f.text()));modal(`<h2>バックアップを読み込みますか？</h2><p>${next.nodes.length} 個の目標を読み込み、現在のデータを置き換えます。</p><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button id="confirm-import" class="primary">置き換える</button></div>`);$('#confirm-import').onclick=()=>{state=next;applyPending(state,today);focus=null;save();close();render();toast('バックアップを読み込みました')}}catch(err){toast('読み込めませんでした：'+err.message)}}});
function bindTree(){const canvas=$('.tree-canvas');if(!canvas)return;let start=null,dragging=false;canvas.addEventListener('pointerdown',e=>{const node=e.target.closest('[data-node]');start={x:e.clientX,y:e.clientY,node:node?.dataset.node,pan:{...pan},pointer:e.pointerId};dragging=false});canvas.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>7)dragging=true;if(dragging&&!start.node){const svg=canvas.querySelector('svg'),ratio=svg.viewBox.baseVal.width/canvas.clientWidth;pan={x:start.pan.x+dx*ratio,y:start.pan.y+dy*ratio};svg.querySelector('.tree-transform').setAttribute('transform',`translate(${pan.x} ${pan.y}) scale(${zoom})`)}});window.onpointerup=e=>{if(!start)return;const s=start;start=null;if(s.node){if(!dragging)editor(s.node);else{const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]')?.dataset.node;if(target&&target!==s.node){try{moveNode(state,s.node,target);save();render();toast('目標のつながりを変更しました')}catch(err){toast(err.message)}}}}};canvas.addEventListener('keydown',e=>{const id=e.target.closest('[data-node]')?.dataset.node;if(id&&['Enter',' '].includes(e.key)){e.preventDefault();editor(id)}})}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(names[h]&&view!==h){view=h;render()}});window.addEventListener('focus',()=>{if(dateKey()!==today)render()});if(names[location.hash.slice(1)])view=location.hash.slice(1);render();
